def is_util(name):
    n=(name or '').lstrip(' ').lower()
    return any(n.startswith(p.lower()) for p in UT)
# suspicious: utility keyword anywhere but not prefix
kw=re.compile(r'centerpoint|northern indiana|nipsco|citizens|vectren|american water|ohio valley|electric power|duke|natural gas|midwest|frontier|northern|indiana american|center ?point|n orthern|nort', re.I)
for c in cases:
    n=c['resp'] or ''
    if not is_util(n) and kw.search(n): print('SUSPECT', c['file'], c['page'], repr(n))
for c in cases:
    n=c['resp'] or ''
    if is_util(n): pass
print('util', sum(is_util(c['resp']) for c in cases), 'nonutil', sum(not is_util(c['resp']) for c in cases))
